  "qualidade": {
    "t034": {
      "naturalidade": 95,
      "clareza": 98,
      "adequacao": 100,
      "correcao": 100,
      "critico": false,
      "justificativa": "Cumpre a extensão e as seções solicitadas, demonstra corretamente a média e distingue a incerteza instrumental da dispersão e do intervalo de confiança. Expõe os limites sem extrapolar a base."
    },
    "t035": {
      "naturalidade": 78,
      "clareza": 81,
      "adequacao": 80,
      "correcao": 77,
      "critico": false,
      "justificativa": "Fica abaixo das 180 palavras. A expressão 'a incerteza é o instrumento' prejudica a compreensão; a associação com precisão nominal não é sustentada pela base. Definir um nível de confiança, isoladamente, não basta para estimar a incerteza estatística. Preserva a média e as ressalvas principais."
    },
    "t036": {
      "naturalidade": 91,
      "clareza": 94,
      "adequacao": 98,
      "correcao": 85,
      "critico": false,
      "justificativa": "Apresenta cálculo correto, estrutura didática e extensão adequada, preservando as ressalvas exigidas. Entretanto, chamar a incerteza instrumental de referência de resolução confunde conceitos distintos, sem apoio no protocolo fornecido."
    },
    "t037": {
      "naturalidade": 87,
      "clareza": 88,
      "adequacao": 96,
      "correcao": 73,
      "critico": false,
      "justificativa": "Cumpre estrutura e extensão, calcula corretamente e mantém as ressalvas centrais. Contudo, trata a incerteza como limite de erro absoluto e afirma uma propagação não demonstrada. Chamar a média de 'valor de referência' também introduz ambiguidade desnecessária."
    }
  }
}

